+	struct gether		*port;
 	u16			cdc_filter;
 
 	spin_lock_irqsave(&dev->lock, flags);
-	if (dev->port_usb) {
-		in = dev->port_usb->in_ep;
-		cdc_filter = dev->port_usb->cdc_filter;
+	port = dev->port_usb;
+	if (port) {
